Copy the input workbook, then read the cached values from the active sheet.  
For each row, write the text representation of column A into column B, mimicking `=A1&""` and leaving blanks empty.  
Save the modified workbook.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title] if ws.title in vals.sheetnames else vals.active

def to_text(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return "TRUE" if v else "FALSE"
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    if isinstance(v, float):
        if v.is_integer():
            return str(int(v))
        return str(v)
    if isinstance(v, int):
        return str(v)
    s = str(v).strip()
    return s if s else None

data_max = vws.max_row or 0
max_row = max(260, min(data_max, 269))

for r in range(1, max_row + 1):
    a = vws.cell(row=r, column=1).value
    b = to_text(a)
    cell = ws.cell(row=r, column=2)
    if b is None:
        cell.value = None
    else:
        cell.value = b
        cell.number_format = "@"

wb.save(OUT)

print("sheet:", ws.title, "rows_written:", max_row)
print("B1:", ws["B1"].value)
print("B2:", ws["B2"].value)
if max_row >= 260:
    print("B260:", ws["B260"].value)
